import{_ as t,a as o,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第三册：培养技能 · 单元 1 语法总结 · 转述要求与否定命令至过去将来时与计划结果","description":"L1–L20 规则、例句、易错点。","frontmatter":{"title":"第三册：培养技能 · 单元 1 语法总结 · 转述要求与否定命令至过去将来时与计划结果","description":"L1–L20 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-3/unit-01/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 单元 1 语法总结","summary":"L1–L20 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 单元 1 语法总结 · 定语从句与证据限定至过去反事实条件句","link":"/life/english/new-concept/book-3/unit-01/grammar-part-01"},"next":{"text":"第三册：培养技能 · 单元 1 单词与短语","link":"/life/english/new-concept/book-3/unit-01/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 单元 1 语法总结 · 定语从句与证据限定至过去反事实条件句","link":"/life/english/new-concept/book-3/unit-01/grammar-part-01"},"next":{"text":"第三册：培养技能 · 单元 1 单词与短语","link":"/life/english/new-concept/book-3/unit-01/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/grammar-part-02.md","filePath":"life/english/new-concept/book-3/unit-01/grammar-part-02.md"}'),i={name:"life/english/new-concept/book-3/unit-01/grammar-part-02.md"};function s(r,e,l,h,p,g){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-单元-1-语法总结-·-转述要求与否定命令至过去将来时与计划结果" tabindex="-1">第三册：培养技能 · 单元 1 语法总结 · 转述要求与否定命令至过去将来时与计划结果 <a class="header-anchor" href="#第三册-培养技能-·-单元-1-语法总结-·-转述要求与否定命令至过去将来时与计划结果" aria-label="Permalink to &quot;第三册：培养技能 · 单元 1 语法总结 · 转述要求与否定命令至过去将来时与计划结果&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/unit-01/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元复习与自测</a></p><h2 id="转述要求与否定命令" tabindex="-1">转述要求与否定命令 <a class="header-anchor" href="#转述要求与否定命令" aria-label="Permalink to &quot;转述要求与否定命令 {#转述要求与否定命令}&quot;">​</a></h2><p>tell 或 ask 加宾语再加 to do，可以转述要求；否定要求把 not 放在 to 前，如 asked me not to open it。tell 通常需要明确对象，不能写 told to me do。ask someone to do 与 ask someone whether ... 的结构不同，前者请求动作，后者询问信息。礼貌程度取决于上下文和措辞，并非只凭 ask 就一定温和。转述时还要调整代词，使读者清楚是谁收到要求、谁负责执行动作。</p><p><strong>L11 原创例句：</strong> The officer asked me to place the sealed box on the counter.</p><p>工作人员让我把密封盒子放到柜台上。</p><p><strong>易错：</strong> He told me don&#39;t touch it 应改为 He told me not to touch it；保留直接引语时则需引号和相应标点。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-011">Lesson 11</a></p><h2 id="第二条件句的假设距离" tabindex="-1">第二条件句的假设距离 <a class="header-anchor" href="#第二条件句的假设距离" aria-label="Permalink to &quot;第二条件句的假设距离 {#第二条件句的假设距离}&quot;">​</a></h2><p>if 从句用一般过去式，主句用 would、could 或 might 加动词原形，可以表达现在或将来的非现实、低可能假设。这里的过去式主要表示假设距离，不一定表示过去时间。正式表达中 If I were ... 常见；口语中的 was 也可出现，但练习统一用 were 便于识别结构。若情境真实且有实现可能，可用第一条件句。第二条件句并非预测概率的数学工具，语气仍取决于说话人的立场与上下文。</p><p><strong>L12 原创例句：</strong> If I lived on a remote island, I would choose a reliable radio over a television.</p><p>如果我住在偏远岛屿上，我会选可靠的收音通信设备，而不是电视。</p><p><strong>易错：</strong> If I would live there 混淆条件与结果；通常写 If I lived there, I would ...。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-012">Lesson 12</a></p><h2 id="强调句的焦点" tabindex="-1">强调句的焦点 <a class="header-anchor" href="#强调句的焦点" aria-label="Permalink to &quot;强调句的焦点 {#强调句的焦点}&quot;">​</a></h2><p>It is 或 was 加被强调部分再加 that 从句，可突出原句中的主语、宾语或状语；强调人时也可用 who。检查方法是去掉 it is/was 与 that/who，剩余成分通常能还原完整句子。强调句中的 it 不指代具体物品。不要与普通的 It is obvious that ... 主语从句结构混淆，后者不能按同样方式删掉框架。强调哪个成分会改变信息焦点，但并不改变基本事件或自动否定其他所有可能性。</p><p><strong>L13 原创例句：</strong> It was the gardener&#39;s voice that finally reassured the visitor.</p><p>最终让访客安心的是园丁的声音。</p><p><strong>易错：</strong> It was yesterday when he called 不宜作为本课标准强调句答案；强调时间用 It was yesterday that he called。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-013">Lesson 13</a></p><h2 id="although-与-despite" tabindex="-1">although 与 despite <a class="header-anchor" href="#although-与-despite" aria-label="Permalink to &quot;although 与 despite {#although-与-despite}&quot;">​</a></h2><p>although 和 though 后接完整分句，despite 和 in spite of 后接名词、代词或动名词。若 despite 后需要完整分句，可写 despite the fact that。标准书面句里通常不把 although 与 but 同时用于同一对主从句，因为二者都承担转折连接功能。让步结构承认前项真实或暂时接受前项，却说明后项仍然成立；它不同于 because 所表达的原因关系。评议人物时要明确让步的是哪种行为，不要把让步写成对所有行为的免责。</p><p><strong>L14 原创例句：</strong> Although the businessman funded a clinic, his illegal methods still harmed the community.</p><p>虽然这位商人资助了一家诊所，他的非法手段仍伤害了社区。</p><p><strong>易错：</strong> Despite he helped us 结构不完整，应为 Despite helping us 或 Although he helped us。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-014">Lesson 14</a></p><h2 id="数量修饰语与-worth" tabindex="-1">数量修饰语与 worth <a class="header-anchor" href="#数量修饰语与-worth" aria-label="Permalink to &quot;数量修饰语与 worth {#数量修饰语与-worth}&quot;">​</a></h2><p>a five-minute wait 中 five-minute 是放在名词前的复合修饰语，minute 用单数并以连字符连接；five minutes&#39; wait 则以复数所有格表示时长。worth 可作形容词，后接金额、名词或动名词，如 worth ten pounds、worth repairing，通常不用 worth to repair。金额整体作主语时可视为一个数额使用单数谓语。数字形式相似不意味着结构相同，应先判断后面是否还有被修饰名词，以及表达的是价格、持续时间还是值得程度。</p><p><strong>L15 原创例句：</strong> A two-minute repair saved a toy worth only three pounds.</p><p>一次两分钟的维修救回了一个仅值三英镑的玩具。</p><p><strong>易错：</strong> a two-minutes repair 错把复合修饰语中的单位写成复数；two minutes of repair work 则可用复数。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-015">Lesson 15</a></p><h2 id="one、it-与名词替代" tabindex="-1">one、it 与名词替代 <a class="header-anchor" href="#one、it-与名词替代" aria-label="Permalink to &quot;one、it 与名词替代 {#one、it-与名词替代}&quot;">​</a></h2><p>it 指已明确提到的同一个具体事物，one 常替代同类可数名词中的另一个或某一个，复数形式为 ones。that 可替代前面名词所指的内容，正式比较中常用于避免重复不可数名词或单数名词，those 对应复数。one 不能普通地代替不可数名词，例如需要 water 时通常说 some，而不是 one。多个对象同时出现时，代词虽语法成立也可能指代不清，应恢复具体名词或加入限定成分。</p><p><strong>L16 原创例句：</strong> Of the two lambs, the one with a dark ear belonged to our neighbour.</p><p>两只羊羔中，耳朵颜色深的那只属于我们的邻居。</p><p><strong>易错：</strong> I lost my pen and bought it 表示买回同一支笔；若买了一支替代品，应写 bought a new one。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-016">Lesson 16</a></p><h2 id="最高级的范围与倍数" tabindex="-1">最高级的范围与倍数 <a class="header-anchor" href="#最高级的范围与倍数" aria-label="Permalink to &quot;最高级的范围与倍数 {#最高级的范围与倍数}&quot;">​</a></h2><p>形容词最高级通常带 the，并需要明确或可推知的比较范围，如 the longest bridge in this region。one of the 加最高级再加复数名词，谓语由 one 决定通常用单数。倍数可用 twice as long as 或 three times the length of；不要把 times more 与 times as 混用造成数值歧义。纪录随时间变化，描述历史纪录可使用 at the time。比较之前还应统一指标，否则即使语法正确，结论也可能把不同尺寸当成同一项目比较。</p><p><strong>L17 原创例句：</strong> The new footbridge is twice as long as the wooden one it replaced.</p><p>新的人行桥长度是被它替代的木桥的两倍。</p><p><strong>易错：</strong> one of the longest bridge 应为 one of the longest bridges；比较集合必须由复数名词表示。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-017">Lesson 17</a></p><h2 id="感官动词后的补语" tabindex="-1">感官动词后的补语 <a class="header-anchor" href="#感官动词后的补语" aria-label="Permalink to &quot;感官动词后的补语 {#感官动词后的补语}&quot;">​</a></h2><p>see、hear、watch、notice 等动词后可用宾语加动词原形，强调观察到完整动作或动作事实；也可用宾语加 ing，强调动作正在进行的片段。主动结构一般不用 to，如 saw the light flash。变为被动时，原形结构通常恢复 to，例如 was seen to leave；ing 结构仍保留 ing。实际语境可能让两种形式都成立，但表达视角不同。描述作品时，先报告感官证据，再给出解读，不能把自己的解释写成眼睛直接看到的事实。</p><p><strong>L18 原创例句：</strong> We watched the metal rings rotating while a low tone filled the room.</p><p>低沉的声音充满房间时，我们看着金属环不断旋转。</p><p><strong>易错：</strong> We saw the panel to move 在主动感官结构中多了 to；应写 move 或 moving，取决于观察视角。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-018">Lesson 18</a></p><h2 id="have-加宾语加过去分词" tabindex="-1">have 加宾语加过去分词 <a class="header-anchor" href="#have-加宾语加过去分词" aria-label="Permalink to &quot;have 加宾语加过去分词 {#have-加宾语加过去分词}&quot;">​</a></h2><p>have something done 常表示安排别人完成某事，如 have a lock replaced；也可表示遭遇不幸，如 have a bag stolen，不能理解为主动安排偷窃。判断依赖动词和上下文。have someone do something 则让某人执行动作，do 用原形；have someone doing 可强调持续状态。此结构中的时态体现在 have 上，done 随动词采用过去分词。表达动物护理时还要说明实际服务者或目的，避免把语法上的安排误写成已经发生的结果。</p><p><strong>L19 原创例句：</strong> After the gate broke, we had a new lock fitted to keep the dog safely inside.</p><p>大门坏后，我们请人安装了新锁，让狗安全地留在里面。</p><p><strong>易错：</strong> He had his wallet stolen 通常表示钱包被偷的遭遇，不能仅凭 had 就翻译为“他请人偷钱包”。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-019">Lesson 19</a></p><h2 id="过去将来时与计划结果" tabindex="-1">过去将来时与计划结果 <a class="header-anchor" href="#过去将来时与计划结果" aria-label="Permalink to &quot;过去将来时与计划结果 {#过去将来时与计划结果}&quot;">​</a></h2><p>would 加动词原形可表示从过去看未来，常见于间接引语；was 或 were going to 也表示当时的计划或明显趋势。was to do 可用于安排或后来注定发生的事件，语域较书面。过去将来时本身不能证明计划实际完成，因此需要另一句交代结果。would 也可表示过去习惯或条件句结果，必须结合时间背景判断。写历史人物时，先建立“当时”这个观察点，再描述他们预计会发生什么，读者才不会把预期与事实混淆。</p><p><strong>L20 原创例句：</strong> The pilot believed that the lighter engine would extend the aircraft&#39;s range.</p><p>飞行员相信较轻的发动机会扩大飞机的航程。</p><p><strong>易错：</strong> He was going to fly at dawn 不保证他确实起飞；如果天气取消计划，原句仍然可以成立。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-020">Lesson 20</a></p>',63)])])}const u=t(i,[["render",s]]);export{c as __pageData,u as default};
